/// The launcher icons the app can wear. Each maps to an `<activity-alias>` in
/// AndroidManifest.xml (see AppActivity.kt) and to art generated by
/// `mobile/tool/icons/generate_icons.py`.
///
/// Only real shop milestones and alerts select an icon. It never cycles just
/// because the date or time changed.
enum AppIconVariant {
  /// Orange Axon cube: the everyday icon.
  standard('standard', 'Open for business', 'The everyday Counterbase icon.',
      AppIconKind.standard, 0),

  /// Flame badge: the shop is on a multi-day trading streak.
  streak(
      'streak',
