  /// Preview art bundled with the app (generated with the icon set).
  String get previewAsset => 'assets/images/app_icons/$key.png';
}

enum AppIconKind { standard, streak, alert, record }

/// What the icon decides from. All of it is computed on this phone from the
/// shop's own data; nothing about it is sent anywhere.
@immutable
class AppIconSignals {
  const AppIconSignals({
    required this.now,
    this.tradingStreakDays = 0,
    this.outOfStockCount = 0,
    this.isRecordDay = false,
    this.salesTodayCount = 0,
  });

  final DateTime now;

  /// Consecutive days with at least one sale, counting back from today (or from
  /// yesterday while today has no sale yet, so the streak is not lost by 9am).
  final int tradingStreakDays;
  final int outOfStockCount;
  final bool isRecordDay;

  /// Counted, non-voided sales today. Used only to choose a record-day look.
  final int salesTodayCount;
}

/// How many days in a row make a streak worth showing.
const int streakShownFromDays = 3;

/// Which icon to wear. Highest priority first:
/// record day, streak, out-of-stock alert, everyday icon.
AppIconVariant chooseAppIcon(AppIconSignals s) {
  if (s.isRecordDay) {
    if (s.salesTodayCount >= 200) return AppIconVariant.gold200;
    if (s.salesTodayCount >= 100) return AppIconVariant.gold100;
    if (s.salesTodayCount >= 50) return AppIconVariant.gold50;
    if (s.salesTodayCount >= 20) return AppIconVariant.gold20;
    if (s.salesTodayCount >= 10) return AppIconVariant.gold10;
    if (s.salesTodayCount >= 5) return AppIconVariant.gold5;
    return AppIconVariant.gold;
  }
  if (s.tradingStreakDays >= streakShownFromDays) {
    if (s.tradingStreakDays >= 12) return AppIconVariant.streak12;
    if (s.tradingStreakDays >= 11) return AppIconVariant.streak11;
    if (s.tradingStreakDays >= 10) return AppIconVariant.streak10;
    if (s.tradingStreakDays >= 9) return AppIconVariant.streak9;
    if (s.tradingStreakDays >= 8) return AppIconVariant.streak8;
    if (s.tradingStreakDays >= 7) return AppIconVariant.streak7;
    if (s.tradingStreakDays >= 6) return AppIconVariant.streak6;
    return AppIconVariant.streak;
  }
  if (s.outOfStockCount >= 9) return AppIconVariant.alert9;
  if (s.outOfStockCount >= 8) return AppIconVariant.alert8;
  if (s.outOfStockCount >= 7) return AppIconVariant.alert7;
  if (s.outOfStockCount >= 6) return AppIconVariant.alert6;
  if (s.outOfStockCount >= 5) return AppIconVariant.alert5;
  if (s.outOfStockCount >= 4) return AppIconVariant.alert4;
  if (s.outOfStockCount >= 3) return AppIconVariant.alert3;
  if (s.outOfStockCount > 0) return AppIconVariant.alert;
  return AppIconVariant.standard;
}

String _dayKey(DateTime d) =>
    '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';

String appIconChangeReason(
  AppIconVariant variant, {
  required bool automaticEnabled,
}) {
  if (!automaticEnabled && variant == AppIconVariant.standard) {
    return 'Automatic icon changes are off, so Counterbase returned to its everyday icon.';
  }
  return switch (variant) {
    AppIconVariant.standard =>
      'Your shop has no current record day, sales streak or out-of-stock alert.',
    _ => variant.blurb,
  };
}

/// Works out the streak and record day from the shop's own sales.
///
/// [dailyTotals] / [dailyCounts] map a day (yyyy-MM-dd) to that day's takings
/// and number of counted sales; only days with sales appear. Pure so it can be
/// tested without a database.
@visibleForTesting
AppIconSignals signalsFromDailyTotals({
  required DateTime now,
  required Map<String, double> dailyTotals,
  required Map<String, int> dailyCounts,
  required int outOfStockCount,
}) {
  final today = _dayKey(now);
  final soldToday = (dailyCounts[today] ?? 0) > 0;

  // Streak: walk back from today (or yesterday if nothing sold yet today).
  var cursor = DateTime(now.year, now.month, now.day);
  if (!soldToday) cursor = cursor.subtract(const Duration(days: 1));
  var streak = 0;
  while ((dailyCounts[_dayKey(cursor)] ?? 0) > 0) {
    streak++;
    cursor = cursor.subtract(const Duration(days: 1));
  }

  // Record day: today beats every earlier day, with enough history and sales
  // that it means something.
  final todayTotal = dailyTotals[today] ?? 0;
  final earlier = [
    for (final e in dailyTotals.entries)
      if (e.key != today) e.value,
  ];
  final isRecord = soldToday &&
      (dailyCounts[today] ?? 0) >= 3 &&
      earlier.length >= 3 &&
      todayTotal > earlier.reduce((a, b) => a > b ? a : b);

  return AppIconSignals(
    now: now,
    tradingStreakDays: streak,
    outOfStockCount: outOfStockCount,
    isRecordDay: isRecord,
    salesTodayCount: dailyCounts[today] ?? 0,
  );
}

/// Switches the launcher icon to match how the shop is doing.
///
/// Always enabled. Android can only swap between icons that ship in the app,
/// and the swap has two side effects this
/// class is built around:
///  * a launcher may delete the home-screen shortcut when its icon is
///    switched, so changes are rare (at most one per [minGap]) and the owner
///    can put the shortcut back with [pinCurrentIcon];
///  * switching while the app is open closes it, so nothing is applied until
///    the app goes to the background ([refresh] is called from there).
class AppIconService {
  AppIconService({
    AppDatabase? database,
    MethodChannel? channel,
    DateTime Function()? clock,
    Future<AppIconSignals> Function(DateTime now, SharedPreferences prefs)?
        signalsLoader,
  })  : _db = database,
        _channel = channel ?? const MethodChannel('axon_pos/app_icon'),
        _clock = clock ?? DateTime.now,
        _signalsLoader = signalsLoader;

  final AppDatabase? _db;
  final MethodChannel _channel;
  final DateTime Function() _clock;
  final Future<AppIconSignals> Function(DateTime now, SharedPreferences prefs)?
      _signalsLoader;

  static const changedAtPref = 'living_app_icon_changed_at_ms';

  /// Do not change the icon more often than this, so a launcher that drops the
  /// shortcut on a switch does so rarely.
  static const minGap = Duration(hours: 20);

  Future<bool> isEnabled() async => true;

  /// Kept for callers from older app versions. The living icon is automatic
  /// and cannot be disabled by a workspace preference.
  @Deprecated('The app icon follows shop activity automatically.')
  Future<void> setEnabled(bool on) async {}

  /// The icon the launcher is showing right now.
  Future<AppIconVariant> current() async {
    try {
      final key = await _channel.invokeMethod<String>('getIcon');
      return AppIconVariant.fromKey(key);
    } on MissingPluginException {
      return AppIconVariant.standard; // not Android, or running in a test
    } on PlatformException {
      return AppIconVariant.standard;
    }
  }

  /// Asks Android to put the current icon on the home screen (the owner sees a
  /// system confirmation). Returns false when the launcher cannot do it.
  Future<bool> pinCurrentIcon() async {
    try {
      return await _channel.invokeMethod<bool>('pinCurrentIcon') ?? false;
    } on MissingPluginException {
      return false;
    } on PlatformException {
      return false;
    }
  }

  /// Brings the launcher icon in line with the owner's choice and the shop's
  /// state. Call it only when the app is going to the background.
  ///
  /// * moves to the icon the shop's activity calls for, at most once per
  ///   [minGap] (unless [force]).
  /// Returns the icon in effect afterwards.
  Future<AppIconVariant> refresh({bool force = false}) async {
    final prefs = await SharedPreferences.getInstance();
    final active = await current();

    final now = _clock();
    final loader = _signalsLoader ?? loadSignals;
    final target = chooseAppIcon(await loader(now, prefs));
    if (target == active) return active;

    final lastChange = prefs.getInt(changedAtPref);
    final recently = lastChange != null &&
        now.millisecondsSinceEpoch - lastChange < minGap.inMilliseconds;
    if (!force && recently) return active;

    if (await _apply(target, prefs)) return target;
    return current();
  }

  Future<AppIconSignals> loadSignals(
      DateTime now, SharedPreferences prefs) async {
    final db = _db;
    if (db == null) return AppIconSignals(now: now);
    final since = DateTime(now.year, now.month, now.day)
        .subtract(const Duration(days: 60));
    final sales = await db.getSalesByDateRange(since, now);
    final totals = <String, double>{};
    final counts = <String, int>{};
    for (final s in sales) {
      if (s.voidedAt != null || s.status.toUpperCase() == 'VOIDED') continue;
      final key = _dayKey(s.createdAt);
      totals[key] = (totals[key] ?? 0) + s.total;
      counts[key] = (counts[key] ?? 0) + 1;
    }

    var outOfStock = 0;
    try {
      final stock = await db.getInventoryReport();
      outOfStock = stock.where((r) => ((r['stock'] as num?) ?? 0) <= 0).length;
    } catch (_) {
      // No stock data yet: do not raise an alert on a guess.
    }

    return signalsFromDailyTotals(
      now: now,
      dailyTotals: totals,
      dailyCounts: counts,
      outOfStockCount: outOfStock,
    );
  }

  Future<bool> _apply(AppIconVariant variant, SharedPreferences prefs) async {
    try {
      final applied =
          await _channel.invokeMethod<bool>('setIcon', {'key': variant.key});
      if (applied != true) return false;
      if (await current() != variant) return false;
      await prefs.setInt(changedAtPref, _clock().millisecondsSinceEpoch);
      return true;
    } on MissingPluginException {
      // Not Android (or a test without the channel): nothing to switch.
      return false;
    } on PlatformException catch (e) {
      debugPrint('[AppIcon] switch to ${variant.key} failed: ${e.message}');
      return false;
    }
  }
}
